/*
 * pvr_pds_render_gen.h
 *
 * The PDS programs of a TA + 3D render on BXS-4-64 (BVNC 36.53.104.796),
 * generated by Mesa 26.2.1's PDS generators (pvr_pds_render_gen.c).
 *
 * These three generators feed a TA + 3D "clear/fill" render:
 *
 *   1. pvr_pds_render_clear_vertex_program()  -- VDM vertex-fetch PDS program
 *      that DMAs the clear-rect vertices into the VS input regs and kicks the
 *      vertex USC.  (Mesa: pvr_pds_vertex_shader / pvr_clear.c clear vertex
 *      program.)
 *
 *   2. pvr_pds_render_kick_usc_program()      -- fragment "kick USC" PDS
 *      program pointed to by TA_STATE_PDS_SHADERBASE.  (Mesa: pvr_pds_kick_usc
 *      / pvr_pds_setup_doutu, pvr_clear.c pixel program.)
 *
 *   3. pvr_pds_render_color_upload_program()  -- pixel "secondary attribute"
 *      texture-DMA PDS program that copies the fill-colour dwords into the
 *      shared registers the captured clear-attachment FS reads
 *      (PVR_CLEAR_ATTACH_DATA_DWORD0..3).  (Mesa:
 *      pvr_pds_pixel_shader_uniform_texture_{data,code} with
 *      num_texture_dma_kicks = 1, pvr_clear.c / pvr_blit.c.)
 *
 * This header needs only <stdint.h>; the .c includes Mesa's
 * (driver/compat/pvr_mesa.h).
 *
 * Device features assumed (from Mesa device_info/bxs-4-64.h):
 *   has_pds_ddmadt            = true   (does not change any of these programs;
 *                                       relevant only when a stream sets
 *                                       use_ddmadt, which the clear path never
 *                                       does)
 *   has_slc_mcu_cache_controls = false (absent -> no SLC cache-mode bits are
 *                                       OR'd into DMA addresses / DOUTW control)
 * Both are exposed as parameters so the code stays correct if reused elsewhere.
 */
#ifndef PVR_PDS_RENDER_GEN_H
#define PVR_PDS_RENDER_GEN_H

#include <stdint.h>

/* Sample rate: fragment kick uses INSTANCE (== 0). defs.h DOUTU_SAMPLE_RATE. */
#define PVR_PDS_RENDER_SAMPLE_RATE_INSTANCE 0u

/* Mesa _PVR_CLEAR_ATTACH_DATA_COUNT (pvr_iface.h): 4 colour dwords + 2 tile
 * address dwords.  This is the DOUTD burst size Mesa uses for the clear colour
 * upload.  For a pure register-output clear the FS reads only DWORD0..3, but
 * Mesa still bursts all 6; pass 4 if your capture buffer holds only the colour.
 */
#define PVR_CLEAR_ATTACH_DATA_COUNT 6u

/* Clear-rect vertex layout (Mesa pvr_clear.h): 4 vertices, 3 f32 coords each,
 * triangle strip; per-vertex stride = 3*4 = 12 bytes, DMA size = 12 bytes. */
#define PVR_CLEAR_VERTEX_COUNT 4u
#define PVR_CLEAR_VERTEX_COORDINATES 3u

/* ------------------------------------------------------------------------- *
 * 1. Vertex (VDM) PDS program for the clear rect.
 * ------------------------------------------------------------------------- */

/* Info needed to program the VDMCTRL VDM_STATE words (vdm.xml). */
struct pvr_pds_render_vertex_info {
   uint32_t data_size_dw;  /* PDS data segment size, in dwords. */
   uint32_t code_size_dw;  /* PDS code segment size, in dwords. */
   uint32_t temps_used;    /* PDS temporaries used. */

   /* --- Field values for the VDM control stream --- *
    * VDM_STATE2.vs_pds_data_base_addr  = <PDS-heap-relative byte offset of the
    *                                      uploaded DATA segment> (16-byte
    *                                      aligned; csb field shift = 4).
    * VDM_STATE3.vs_pds_code_base_addr  = <PDS-heap-relative byte offset of the
    *                                      uploaded CODE segment> (16-byte
    *                                      aligned; csb field shift = 4).
    * VDM_STATE5.vs_pds_data_size       = vdm_pds_data_size_units
    * VDM_STATE5.vs_pds_temp_size       = vdm_pds_temp_size_units
    * VDM_STATE5.vs_usc_unified_size    = vdm_usc_unified_size_units
    * The two base offsets are chosen by the caller at upload time.
    */
   uint32_t vdm_pds_data_size_units;   /* DIV_ROUND_UP(data_size_dw*4, 16). */
   uint32_t vdm_pds_temp_size_units;   /* DIV_ROUND_UP(temps_used*4, 16).    */
   uint32_t vdm_usc_unified_size_units;/* DIV_ROUND_UP(vtxin_bytes, 16).     */
};

/*
 * Generate the clear-rect vertex-fetch PDS program (data + code).
 *
 * Inputs:
 *   vs_usc_exec_offset : VS USC shader entry, as a byte offset RELATIVE to the
 *                        USC heap base (4-byte aligned; bits [31:2] used).
 *   vs_temps           : number of PDS temporaries the caller wants reflected
 *                        in the DOUTU task control (usually 0 for clear;
 *                        the generator always uses >=2 PDS temps internally).
 *   vertex_buf_addr    : GPU device address of the clear-rect vertex buffer.
 *   vertex_stride      : per-vertex stride in bytes (12 for the clear rect).
 *   vertex_dma_size    : bytes DMAed per vertex into the VS input regs
 *                        (12 for the clear rect: x,y,z).
 *   vertex_dst_reg     : first VS input (vtxin) register to receive the DMA
 *                        (0 for the clear rect).
 *   has_slc_mcu_cache_controls : device feature bit (false on BXS-4-64).
 *
 * Outputs (little-endian uint32 arrays):
 *   data_out : >= 8 dwords.
 *   code_out : >= 3 dwords.
 *   info     : sizes + VDM field values (may be NULL).
 *
 * Returns 0 on success, non-zero on bad input.
 */
int pvr_pds_render_clear_vertex_program(uint64_t vs_usc_exec_offset,
                                        uint32_t vs_temps,
                                        uint64_t vertex_buf_addr,
                                        uint32_t vertex_stride,
                                        uint32_t vertex_dma_size,
                                        uint32_t vertex_dst_reg,
                                        int has_slc_mcu_cache_controls,
                                        uint32_t *data_out,
                                        uint32_t *code_out,
                                        struct pvr_pds_render_vertex_info *info);

/* ------------------------------------------------------------------------- *
 * 2. Fragment "kick USC" PDS program (TA_STATE_PDS_SHADERBASE).
 * ------------------------------------------------------------------------- */

struct pvr_pds_render_kick_usc_info {
   uint32_t data_size_dw;   /* Always 8 (ROGUE_PDS_FIXED_PIXEL_SHADER_DATA_SIZE). */
   uint32_t code_size_dw;   /* Always 1 (single DOUTU). */
   uint32_t doutu_offset;   /* Data-segment dword offset of the DOUTU task ctrl. */
};

/*
 * Generate the fragment kick-USC PDS program (data + code).
 *
 * Mesa lays this out as one CODEDATA buffer: DATA (8 dwords) first, CODE
 * (1 dword) immediately after; TA_STATE_PDS_SHADERBASE points at the DATA
 * base.  This function fills the two segments into separate arrays; concatenate
 * them (data then code) when you upload, and point SHADERBASE at the data base.
 *
 * Inputs:
 *   fs_usc_exec_offset : FS USC shader entry, byte offset RELATIVE to the USC
 *                        heap base (4-byte aligned).
 *   fs_temps           : number of USC temporaries the FS uses.
 *   sample_rate        : PVR_PDS_RENDER_SAMPLE_RATE_INSTANCE for a clear.
 *
 * Outputs:
 *   data_out : >= 8 dwords.
 *   code_out : >= 1 dword.
 *   info     : sizes / doutu offset (may be NULL).
 *
 * Returns 0 on success.
 */
int pvr_pds_render_kick_usc_program(uint64_t fs_usc_exec_offset,
                                    uint32_t fs_temps,
                                    uint32_t sample_rate,
                                    uint32_t *data_out,
                                    uint32_t *code_out,
                                    struct pvr_pds_render_kick_usc_info *info);

/* ------------------------------------------------------------------------- *
 * 3. Colour shared-register upload PDS program (texture / SA DMA).
 * ------------------------------------------------------------------------- */

struct pvr_pds_render_color_upload_info {
   uint32_t data_size_dw;   /* Always 3. -> TA_STATE_PDS_SIZEINFO1.pds_texturestatesize
                             *    = DIV_ROUND_UP(data_size_dw*4, 4) = data_size_dw. */
   uint32_t code_size_dw;   /* Always 2 (DOUTD + HALT). */
   uint32_t temps_used;     /* Always 1. -> TA_STATE_PDS_SIZEINFO1.pds_tempsize
                             *    = DIV_ROUND_UP(temps_used, 4). */
};

/*
 * Generate the colour-upload (pixel secondary-attribute texture-DMA) PDS
 * program (data + code) with a single DMA kick.
 *
 * The DMA copies `dma_dword_count` dwords from `color_buf_addr` into the
 * Common Store starting at attribute offset `dest_offset` (0 for a clear).
 * The captured clear FS then reads PVR_CLEAR_ATTACH_DATA_DWORD0..3 from there.
 *
 * The code segment goes to TA_STATE_PDS_TEXUNICODEBASE; the data segment goes
 * to TA_STATE_PDS_TEXTUREDATABASE.  Code and data live in SEPARATE uploads
 * (unlike the kick-USC program).
 *
 * Inputs:
 *   color_buf_addr    : GPU device address of the constant buffer holding the
 *                       colour dwords (buffer must hold >= dma_dword_count
 *                       dwords; Mesa's clear buffer is
 *                       [color0..3, tile_addr_lo, tile_addr_hi]).
 *   dma_dword_count   : dwords to burst (PVR_CLEAR_ATTACH_DATA_COUNT = 6 to
 *                       match Mesa's clear-attach; 4 for colour only).
 *   dest_offset       : Common-Store attribute offset of the first dword (0).
 *   has_slc_mcu_cache_controls : device feature bit (false on BXS-4-64).
 *
 * Outputs:
 *   data_out : >= 3 dwords.
 *   code_out : >= 2 dwords.
 *   info     : sizes / temps (may be NULL).
 *
 * Returns 0 on success, non-zero on bad input.
 */
int pvr_pds_render_color_upload_program(uint64_t color_buf_addr,
                                        uint32_t dma_dword_count,
                                        uint32_t dest_offset,
                                        int has_slc_mcu_cache_controls,
                                        uint32_t *data_out,
                                        uint32_t *code_out,
                                        struct pvr_pds_render_color_upload_info *info);

/* ------------------------------------------------------------------------- *
 * 4. General vertex-fetch PDS program: one DMA stream per vertex attribute.
 *
 * Generalisation of (1) to N streams, following pvr_pds_vertex_shader()
 * exactly (one DDMAD per stream, LAST_EN on the final DMA, then DOUTU + HALT).
 * Constant layout is Mesa's: [0,1] DOUTU control; per stream i an 8-dword
 * block at 8*i with stride @+2, address @+4..5, control @+6..7 (block 0 shares
 * its first two dwords with the DOUTU control). Data size = 8 * num_streams.
 * This is what a GL glVertexAttribPointer set maps to: each enabled attribute
 * is a stream {buffer VA + offset, stride, size, first vi register}.
 * ------------------------------------------------------------------------- */
struct pvr_pds_render_stream {
   uint64_t address;     /* GPU VA of the first vertex of this attribute */
   uint32_t stride;      /* bytes between vertices */
   uint32_t dma_size;    /* bytes DMAed per vertex (rounded up to dwords) */
   uint32_t dst_reg;     /* first vtxin (vi) register */
   /* 1: one element per instance (GL divisor 1): indexed by the instance
    * number (IR1) instead of the vertex index (IR0). Honoured by
    * pvr_pds_render_vertex_program_ids(). */
   uint32_t per_instance;
};

#define PVR_PDS_VERTEX_MAX_STREAMS 16u

/*
 * data_out : >= 8 * num_streams dwords.
 * code_out : >= num_streams + 2 dwords.
 * info     : as for (1); vdm_usc_unified_size_units covers the highest vi
 *            register any stream writes.
 * Returns 0 on success, non-zero on bad input.
 */
int pvr_pds_render_vertex_program(uint64_t vs_usc_exec_offset,
                                  uint32_t vs_temps,
                                  const struct pvr_pds_render_stream *streams,
                                  uint32_t num_streams,
                                  int has_slc_mcu_cache_controls,
                                  uint32_t *data_out,
                                  uint32_t *code_out,
                                  struct pvr_pds_render_vertex_info *info);

/* As above, also writing the vertex index (IR0) and/or the instance index
 * (IR1) into vtxin registers for a shader that reads gl_VertexID /
 * gl_InstanceID (PVR_PDS_NO_ID_REG: not written). data_out needs 8 more
 * dwords and code_out 2 more when either is written. */
#define PVR_PDS_NO_ID_REG 0xffu
int pvr_pds_render_vertex_program_ids(uint64_t vs_usc_exec_offset,
                                      uint32_t vs_temps,
                                      const struct pvr_pds_render_stream *streams,
                                      uint32_t num_streams,
                                      int has_slc_mcu_cache_controls,
                                      uint32_t vertex_id_reg,
                                      uint32_t instance_id_reg,
                                      uint32_t *data_out,
                                      uint32_t *code_out,
                                      struct pvr_pds_render_vertex_info *info);

/* ------------------------------------------------------------------------- *
 * 5. Coefficient-loading (DOUTI) PDS program for the fragment varyings
 *    (TA_STATE_PDS_VARYINGBASE). Port of pvr_pds_coefficient_loading()
 *    driven by pvr_graphics_pipeline_setup_fragment_coeff_program():
 *    one iterator per varying, the 1/w plane first when the FS uses it.
 *    See docs/gpu-recipes/multivarying_coeff_recipe.md (silicon-verified with
 *    two smooth varyings + W).
 * ------------------------------------------------------------------------- */
enum pvr_pds_coeff_interp {
   PVR_PDS_COEFF_SMOOTH = 0,  /* perspective-correct (GOURAUD, perspective=1) */
   PVR_PDS_COEFF_NPC    = 1,  /* linear in screen space (GOURAUD, perspective=0) */
   PVR_PDS_COEFF_FLAT   = 2,  /* FLAT_VERTEX0 */
};

struct pvr_pds_coeff_varying {
   uint32_t components;   /* 1..4 f32 components */
   uint32_t interp;       /* enum pvr_pds_coeff_interp */
   uint32_t vtxout_off;   /* dword offset of the varying in the VS output vector */
};

struct pvr_pds_coeff_info {
   uint32_t data_size_dw;      /* ALIGN(2 * iterators, 4) */
   uint32_t code_size_dw;      /* iterators */
   uint32_t coeff_dwords;      /* coefficient registers consumed (cf0..N-1) */
   uint32_t pds_varyingsize;   /* TA_STATE_PDS_SIZEINFO1.pds_varyingsize (units of 4 dw) */
   uint32_t usc_varyingsize;   /* TA_STATE_PDS_SIZEINFO1.usc_varyingsize (units of 16 dw) */
};

#define PVR_PDS_COEFF_MAX_VARYINGS 16u

/*
 * uses_w   : the FS reads the 1/w plane (perspective varyings) -> iterator 0.
 * uses_z   : the FS reads the z plane (gl_FragCoord.z) -> iterator 0, ahead
 *            of W; the record's uses_z.
 * uses_pntc: the FS reads gl_PointCoord: a point-sprite iterator after W/Z,
 *            two coefficient sets (8 dwords) ahead of the varyings.
 * data_out : >= 2 * (num_varyings + 3) + 2 dwords (padded to 4).
 * code_out : >= num_varyings + 3 dwords.
 * Returns 0 on success, non-zero on bad input.
 */
int pvr_pds_render_coeff_program(int uses_w,
                                 int uses_z,
                                 int uses_pntc,
                                 const struct pvr_pds_coeff_varying *varyings,
                                 uint32_t num_varyings,
                                 uint32_t *data_out,
                                 uint32_t *code_out,
                                 struct pvr_pds_coeff_info *info);

/* ------------------------------------------------------------------------- *
 * 6. Common-store DMA program with N kicks (uniforms, texture/sampler state).
 *    Generalisation of (3): each kick DMAs `dwords` from `address` into the
 *    USC common store at attribute offset `dest_offset`. Constant layout:
 *    addresses first (2 dwords each, 64-bit aligned), then one 32-bit control
 *    word per kick; for a single kick this is byte-identical to (3).
 * ------------------------------------------------------------------------- */
struct pvr_pds_dma_kick {
   uint64_t address;
   uint32_t dwords;
   uint32_t dest_offset;
};

/* One DOUTD per buffer, as Mesa's pvr does (pvr_pds.h
 * PVR_PDS_MAX_NUM_DMA_KICKS 32; pvr_arch_pipeline.c appends one per special
 * buffer). A fragment draw uses up to six: descriptors, uniforms, the
 * discard control word, the front-face op, gl_FragCoord's y pair and the
 * tile-buffer addresses. It was 4, and the caller dropped the rest without
 * a word; the caller now fails the draw when they do not fit. The program's
 * bytes for N kicks do not depend on this bound. */
#define PVR_PDS_DMA_MAX_KICKS 8u

/*
 * data_out : >= 3 * num_kicks dwords.
 * code_out : >= num_kicks + 1 dwords.
 * info     : data_size_dw = 3 * num_kicks, code_size_dw = num_kicks + 1, temps 1.
 */
int pvr_pds_render_dma_program(const struct pvr_pds_dma_kick *kicks,
                               uint32_t num_kicks,
                               int has_slc_mcu_cache_controls,
                               uint32_t *data_out,
                               uint32_t *code_out,
                               struct pvr_pds_render_color_upload_info *info);

#endif /* PVR_PDS_RENDER_GEN_H */
